#include <list>
#include <iostream>

int main() {
    std::list<int> l1 = {1, 5, 8}; // Must be sorted
    std::list<int> l2 = {2, 4, 9}; // Must be sorted

    l1.merge(l2);

    // l1 is now {1, 2, 4, 5, 8, 9}
    // l2 is empty

    std::cout << "l1 size: " << l1.size() << std::endl;
    std::cout << "l2 size: " << l2.size() << std::endl;

    // DANGER: Trying to access l2 elements is UB/error
}
